# -----------------------------------------------------------------------------
# Shared helpers for the PICRUSt2 custom-trait analyses
# (Figure 6D, Figure S6A, Figure S6B).
#
# Sourced by:
# - figure6_scripts/04_plot_figure6d.R
# - figureS6_scripts/01_plot_figureS6a.R
# - figureS6_scripts/02_plot_figureS6b.R
#
# Inputs (data/figure6/, generated by 00_generate_picrust_data.R):
# - asv_taxonomy.csv
# - picrust_marker_nsti.tsv.gz
# - picrust_cazyme_secreted.tsv.gz
# - picrust_cazyme_all_digestive.tsv.gz
# - fig1e_history_samples.csv, fig1e_matched_sets.csv
# - dbcan_fam-substrate-mapping-08012023.tsv
# Plus data/Liao_etal_2021/tblcounts_asv_wide.csv for ASV read counts.
# -----------------------------------------------------------------------------

suppressPackageStartupMessages({
  library(data.table)
})

PICRUST_DATA_DIR <- "data/figure6"
LIAO_ASV_COUNTS <- "data/Liao_etal_2021/tblcounts_asv_wide.csv"

# ASVs above this NSTI are treated as non-assessable by PICRUSt2.
NSTI_MAX <- 2
# Pseudocount for log10 transforms of per-sample features.
EPS <- 1e-6

picrust_path <- function(file) file.path(PICRUST_DATA_DIR, file)

# ASV taxonomy restricted to the ASVs of the Figure 1E design (non-missing
# Phylum). ASVs outside that set have no Phylum/Genus assignment and are
# dropped, matching the inner join with the original Figure 1E taxonomy.
read_asv_taxonomy <- function() {
  tax <- fread(picrust_path("asv_taxonomy.csv"), colClasses = c(ASV = "character"))
  tax <- tax[!is.na(Phylum) & nzchar(Phylum)]
  tax[, phylum := tolower(sub("^[a-z]__", "", trimws(Phylum)))]
  tax[, genus := tolower(sub("^[a-z]__", "", trimws(Genus)))]
  tax[, is_pseudo := grepl("proteobacteria|pseudomonadota", phylum)]
  # Every Bacteroidaceae ASV in this dataset is genus Bacteroides, so the genus
  # label also defines the Bacteroidaceae group.
  tax[, is_bacteroides := !is.na(genus) & genus == "bacteroides"]
  tax[]
}

# Predicted 16S copy number and NSTI per ASV (PICRUSt2 marker prediction).
read_marker <- function() {
  marker <- fread(picrust_path("picrust_marker_nsti.tsv.gz"))
  setnames(marker, c("sequence", "16S_rRNA_Count", "metadata_NSTI"),
           c("ASV", "copy16S", "NSTI"), skip_absent = TRUE)
  marker[, .(ASV = as.character(ASV), copy16S, NSTI)]
}

# PICRUSt2 per-ASV predicted gene copies for the custom CAZyme trait table.
# type = "secreted" (signal-peptide digestive CAZymes) or "all_digestive".
read_predictions <- function(type = c("secreted", "all_digestive")) {
  type <- match.arg(type)
  fread(picrust_path(sprintf("picrust_cazyme_%s.tsv.gz", type)))
}

read_history_samples <- function() {
  fread(picrust_path("fig1e_history_samples.csv"),
        colClasses = c(SampleID = "character", EpisodeID = "character"))
}

read_matched_sets <- function() {
  fread(picrust_path("fig1e_matched_sets.csv"),
        colClasses = c(PatientID = "character", EpisodeID = "character"))
}

# Long-format ASV read counts (SampleID, ASV, Count > 0) for the requested
# stool samples, taken directly from the Liao et al. 2021 ASV count table.
read_liao_asv_counts <- function(sample_ids) {
  header <- names(fread(LIAO_ASV_COUNTS, nrows = 0))
  sample_ids <- unique(as.character(sample_ids))
  missing <- setdiff(sample_ids, header)
  if (length(missing)) stop("Samples missing from ", LIAO_ASV_COUNTS, ": ", paste(head(missing), collapse = ", "))
  wide <- fread(LIAO_ASV_COUNTS, select = c("ASV", sample_ids))
  counts <- melt(wide, id.vars = "ASV", variable.name = "SampleID", value.name = "Count",
                 variable.factor = FALSE)
  counts <- counts[Count > 0]
  counts[, `:=`(SampleID = as.character(SampleID), ASV = as.character(ASV))]
  counts[]
}

split_substrates <- function(x) {
  x <- tolower(trimws(x))
  x <- gsub("\\s*,\\s*", ";", x)
  x <- gsub("\\s+and\\s+", ";", x)
  tokens <- trimws(unlist(strsplit(x, ";", fixed = TRUE)))
  tokens[nzchar(tokens)]
}

# Map resolved Family_EC trait columns to dbCAN high-level substrates using the
# dbCAN family + EC -> substrate table. A column counts fully toward every
# substrate dbCAN lists for its (family, EC); unresolved columns have no EC and
# are not mapped.
make_substrate_colmap <- function(trait_cols) {
  dbcan <- fread(picrust_path("dbcan_fam-substrate-mapping-08012023.tsv"))
  cols <- data.table(col = trait_cols)
  cols[, family := sub("_.*$", "", col)]
  cols[, ec := sub("^[^_]*_", "", col)]
  cols <- cols[ec != "unresolved"]
  db_sub <- dbcan[, .(family = trimws(Family), ec = trimws(EC_Number),
                      substrate_raw = Substrate_high_level)]
  db_sub <- db_sub[!is.na(substrate_raw) & nzchar(trimws(substrate_raw))]
  db_sub <- db_sub[, .(dbcan_substrate = unique(split_substrates(substrate_raw))),
                   by = .(family, ec)]
  colmap <- merge(cols, db_sub, by = c("family", "ec"), allow.cartesian = TRUE)
  unique(colmap[, .(col, dbcan_substrate)])
}

# Per-ASV substrate score: predicted gene copies summed over the resolved trait
# columns mapped to that substrate.
substrate_score <- function(pred, colmap, substrate) {
  m <- colmap[dbcan_substrate == substrate]
  if (!nrow(m)) stop("No trait columns map to substrate: ", substrate)
  mat <- as.matrix(pred[, m$col, with = FALSE])
  storage.mode(mat) <- "numeric"
  rowSums(mat)
}

# Collapse per-sample features to per-history cumulative maxima, attach them to
# the frozen matched sets, and keep complete sets with one case and >= 1 control.
build_model_data <- function(sample_features, feature_cols, membership, matched) {
  hv <- merge(membership, sample_features, by = "SampleID", all.x = TRUE,
              allow.cartesian = TRUE, sort = FALSE)
  histories <- hv[, c(lapply(.SD, function(z) suppressWarnings(max(z, na.rm = TRUE))),
                      .(observed_samples = uniqueN(SampleID))),
                  by = history_id, .SDcols = feature_cols]
  for (col in feature_cols) histories[!is.finite(get(col)), (col) := NA_real_]
  md <- merge(matched, histories, by = "history_id", all.x = TRUE, sort = FALSE)
  md <- md[complete.cases(md[, ..feature_cols])]
  sets_ok <- md[, .(cases = sum(outcome == 1), controls = sum(outcome == 0)), by = set_id][
    cases == 1 & controls >= 1, set_id]
  md[set_id %in% sets_ok]
}
